"""Baseline audit and recovery copies only; never edits raster artwork."""
from pathlib import Path
import json,hashlib,subprocess,shutil
R=Path(__file__).resolve().parents[2];E=Path(__file__).resolve().parent
read=lambda p:json.loads((R/p).read_text(encoding='utf-8-sig'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
active=read('characters/orc-v1/source/equipment-current.json');assert active['revision']=='main-orc-onehanded-v3'
if not (E/'protected-art.json').exists():
 files={str(p.relative_to(R)).replace('\\','/'):sha(p) for folder in ['characters','assets/weapons','ideas'] for p in (R/folder).rglob('*') if p.is_file() and p.suffix.lower() in ['.png','.aseprite','.ase']}
 (E/'protected-art.json').write_text(json.dumps(files,indent=2),encoding='utf-8');(E/'initial-git-status.txt').write_bytes(subprocess.check_output(['git','status','--short'],cwd=R));shutil.copytree(R/'Biblioteca de Arte/Personagens Jogaveis/Orc V1',E/'baseline-review')
 for path in ['characters/orc-v1/character.json','characters/orc-v1/assets.json','characters/orc-v1/source/equipment-current.json','assets/weapons/recruit-sword/weapon.json','assets/weapons/militia-axe/weapon.json','docs/ART_LIBRARY_COMPARISONS.json']:
  target=E/'baseline-metadata'/path;target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(R/path,target)
job=read('experiments/main-orc-weapon-rescue-v3/editor.json');job['id']='main-orc-polish-baseline';job['jobs']=[j for j in job['jobs'] if j['id'] in ['sword-attack','axe-attack']];(E/'baseline-editor.json').write_text(json.dumps(job,indent=2),encoding='utf-8')
classes={'Sword':['KEEP','TRANSITION_FIX','TIMING_ONLY','TIMING_ONLY','MINOR_POLISH','MINOR_POLISH','TRANSITION_FIX','TRANSITION_FIX'],'Axe':['KEEP','TRANSITION_FIX','TIMING_ONLY','TIMING_ONLY','TIMING_ONLY','MINOR_POLISH','TIMING_ONLY','MINOR_POLISH','TRANSITION_FIX','KEEP']}
reasons={'Sword':['Preserve exact current unarmed neutral.','Usable load pose; establish grip before the arm is already displaced.','Keep guard artwork; shorten hold to produce compact anticipation.','Keep drive silhouette; the63px spacing can serve fast acceleration when this hold is shortened.','Keep crossing; inspect wrist/guard overlap on actual composite.','Small masked body correction for hip/leading knee/shoulder commitment; preserve head, feet and glove.','49px single recovery retraction: try current same-Orc Axe7 as bridge, then retime.','Keep neutral pixels; settle with weapon briefly before hiding on identical body.'],'Axe':['Keep neutral.','Keep low-load art; short in-action grip establishment.','Keep lift; remove uniform rhythm.','Keep cocked shoulder; deliberate accent before commitment.','Keep release; shorten70ms mid-motion pause.','Masked hip/knee/shoulder polish and distinct impact emphasis; retain corrected weapon/hand.','Keep follow-through art, retime deceleration.','Keep source pose, check near-leg head clearance and wrist.','Keep settle art; weapon currently disappears while arm is not neutral.','Keep exact neutral; coherent action boundary before hide.']}
audit={'character':'orc-v1','baselineRevision':active['revision'],'sourceTruth':active,'recording':'No new recording attached. Audit uses actual current exports and existing real1x/0.25x preview captures.','scope':'Targeted polish only; current v3 remains baseline until creator accepts candidate. No weapon redesign, runtime, new rig or new framework.','frames':{},'minimumPlan':['Retiming study with identical pixels before body edits','Two limited impact-body retouches, no face/foot/hand regeneration','Reuse current same-Orc Axe7 as Sword recovery transition only if visually compatible','Short attack-onset and finish grip poses, not armed Idle/Walk','Reuse existing preview/compositor, distinct category profiles and actual timing','Independent visual QA on exported candidates, no automatic creator approval']}
for category in classes:
 c=read(f'characters/orc-v1/source/onehanded-rescue-v3/{category}/Attack/clip.json');assert sha(R/c['master'])==c['masterSha256']
 rows=[];last=None
 for i,(f,tag,why) in enumerate(zip(c['frames'],classes[category],reasons[category])):
  grip=f['rightGrip'];d=round(sum((a-b)**2 for a,b in zip(grip,last))**.5,2) if grip and last else None;rows.append({'frame':i,'classification':tag,'reason':why,'durationMs':f['durationMs'],'grip':grip,'handTravelFromPreviousPx':d,'png':f['png'],'bodyMaster':c['bodyMaster']});last=grip
 audit['frames'][category]=rows
(E/'artistic-audit.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps({'protectedArtFiles':len(read('experiments/main-orc-polish-v1/protected-art.json')),'framesClassified':sum(map(len,audit['frames'].values())),'forkManifest':'experiments/main-orc-polish-v1/baseline-editor.json'}))
